create or replace function public.sync_class_teacher_students() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_table_name='class_teachers' then if tg_op='INSERT' then insert into public.teacher_students(teacher_id,student_id) select new.teacher_id,s.id from public.students s where s.class_id=new.class_id on conflict do nothing; elsif tg_op='DELETE' then delete from public.teacher_students ts where ts.teacher_id=old.teacher_id and exists(select 1 from public.students s where s.id=ts.student_id and s.class_id=old.class_id); end if; return coalesce(new,old); end if; if tg_table_name='students' then if tg_op='UPDATE' and old.class_id is distinct from new.class_id then delete from public.teacher_students ts where ts.student_id=new.id and exists(select 1 from public.class_teachers ct where ct.teacher_id=ts.teacher_id and ct.class_id=old.class_id); insert into public.teacher_students(teacher_id,student_id) select ct.teacher_id,new.id from public.class_teachers ct where ct.class_id=new.class_id on conflict do nothing; elsif tg_op='INSERT' and new.class_id is not null then insert into public.teacher_students(teacher_id,student_id) select ct.teacher_id,new.id from public.class_teachers ct where ct.class_id=new.class_id on conflict do nothing; end if; return new; end if; return coalesce(new,old); end $$;
drop trigger if exists class_teachers_sync_students on public.class_teachers;
create trigger class_teachers_sync_students after insert or delete on public.class_teachers for each row execute function public.sync_class_teacher_students();
drop trigger if exists students_sync_class_teachers on public.students;
create trigger students_sync_class_teachers after insert or update of class_id on public.students for each row execute function public.sync_class_teacher_students();
